func (s LiveUpdateKind) Validate() error {
	switch s {
	case "snapshot":
		return nil
	case "view":
		return nil
	case "rejected":
		return nil
	case "ended":
		return nil
	case "path":
		return nil
	case "attack_preview":
		return nil
	case "area_preview":
		return nil
	case "ping":
		return nil
	case "roll":
		return nil
	case "regroup":
		return nil
	case "route_measured":
		return nil
	default:
		return errors.Errorf("invalid value: %v", s)
	}
}

